/** Description: Initializes the DAC register and sets P0.26 and DAC output
*/

void dac_init (void)
{	
	CRITICAL ;
		
	C_ENTER ;			    
	{
		PINMODE1 = (PINMODE1 & ~(3u << 20)) | (2u << 20) ;       // Disable P0.26 PULL UP-DOWN

		PINSEL1  = (PINSEL1  & ~(3u << 20)) | (2u << 20) ;       // Configure P0.26 as DAC_OUT

		PCLKSEL0 |= (1u << 22) ;

		DACR = 0 ;
	}
	C_LEAVE ;
}
